contract HuskyInuTest is Test {
    HuskyInu public token;
    string constant NAME = "HuskyInu";
    string constant SYMBOL = "HUSKY";

    address constant BSC_ROUTER_ADDRESS = 0x10ED43C718714eb63d5aA57B78B54704E256024E;

